<script lang="ts">
 // Local Svelte adaptation of RoutingTales nuevo_editor/editor_Chats.html:
 // visual nodes, message groups, answer targets, success/fail and JSON editing.
 import {onMount,tick} from 'svelte';
 import {beforeNavigate} from '$app/navigation';
 import {Plus,Trash2,Upload,Download,Play,Save,ChevronUp,ChevronDown,ChevronRight} from 'lucide-svelte';
 import RoutingTalesChat from '$lib/components/RoutingTalesChat.svelte';
 import ModuleEditorHeader from '$lib/components/ModuleEditorHeader.svelte';
 import {parseChat,type ChatConfig,type ChatNode} from './routingtales';
 import {createChat,importChat,messageGroups,renameNode,removeNode,reorderNode,MAX_CHAT_BYTES,type AdventureChat} from './editor';
 import {downloadBlob} from '$lib/storage/adventure-package';
 let {chat,title,uses=1,onapply,onclose,ondirty}:{chat?:AdventureChat;title:string;uses?:number;onapply:(name:string,config:ChatConfig)=>void;onclose:()=>void;ondirty:(dirty:boolean)=>void}=$props();
 let config=$state<ChatConfig>(createChat()),name=$state(''),expanded=$state<string[]>([]),tab=$state<'visual'|'json'|'preview'>('visual'),json=$state(''),initial=$state(''),ready=$state(false),error=$state('');
 let preview=$state<ChatConfig>(),previewRevision=$state(0),discarding=$state(false);
 let discardMessage=$state<HTMLDivElement>();
 let fileInput:HTMLInputElement;
 let visualList=$state<HTMLElement>();
 const dirty=$derived(ready&&(JSON.stringify({name,config})!==initial||(tab==='json'&&json!==JSON.stringify(config,null,2))));
 const previewStorage={getItem:()=>null,setItem:()=>{}};
 onMount(()=>{config=JSON.parse(JSON.stringify(chat?.config??createChat()));name=chat?.name??title;expanded=[config.chatNodes[0].id];initial=JSON.stringify({name,config});ready=true;});
 $effect(()=>ondirty(dirty));
 beforeNavigate(event=>{if(dirty&&!confirm('¿Descartar los cambios de esta conversación?'))event.cancel();});
 function leave(){if(dirty)discarding=true;else onclose();}
 $effect(()=>{if(discarding)discardMessage?.focus({preventScroll:true});});
 function keyDown(event:KeyboardEvent){if(event.key==='Escape'&&!event.defaultPrevented){event.preventDefault();leave();}}
 function unload(event:BeforeUnloadEvent){if(dirty){event.preventDefault();event.returnValue='';}}
 function toggleNode(id:string){expanded=expanded.includes(id)?expanded.filter(value=>value!==id):[...expanded,id];}
 function toggleAll(){expanded=config.chatNodes.every(node=>expanded.includes(node.id))?[]:config.chatNodes.map(node=>node.id);}
 async function focusNode(id:string,scroll=false){await tick();const button=Array.from(visualList?.querySelectorAll<HTMLButtonElement>('[data-node-toggle]')??[]).find(button=>button.dataset.nodeToggle===id);button?.focus({preventScroll:true});if(scroll)button?.scrollIntoView({block:'nearest'});}
 function changeNode(nodeIndex:number,values:Partial<ChatNode>){config={...config,chatNodes:config.chatNodes.map((n,i)=>i===nodeIndex?{...n,...values}:n)};error='';}
 function rename(nodeIndex:number,id:string){try{const old=config.chatNodes[nodeIndex].id;config=renameNode(config,nodeIndex,id);expanded=expanded.map(value=>value===old?id:value);error='';void focusNode(id);return true;}catch(e){error=(e as Error).message;return false;}}
 function addNode(id?:string,after=config.chatNodes.length-1){
  if(id&&config.chatNodes.some(node=>node.id===id)){if(!expanded.includes(id))expanded=[...expanded,id];void focusNode(id,true);return;}
  if(config.chatNodes.length>=256){error='La conversación admite hasta 256 nodos.';return;}
  if(!id){let number=1;while(config.chatNodes.some(node=>node.id==='node-'+number))number++;id='node-'+number;}
  const node={id,messages:[['Nuevo mensaje']],options:[]};config={...config,chatNodes:[...config.chatNodes.slice(0,after+1),node,...config.chatNodes.slice(after+1)]};expanded=[...expanded,id];error='';void focusNode(id,true);
 }
 function remove(nodeIndex:number){try{config=removeNode(config,nodeIndex);expanded=expanded.filter(id=>config.chatNodes.some(node=>node.id===id));error='';void focusNode(config.chatNodes[Math.min(nodeIndex,config.chatNodes.length-1)].id);}catch(e){error=(e as Error).message;}}
 function move(nodeIndex:number,delta:number){try{const id=config.chatNodes[nodeIndex].id;config=reorderNode(config,nodeIndex,nodeIndex+delta);error='';void focusNode(id,true);}catch(e){error=(e as Error).message;}}
 function groupText(nodeIndex:number,group:number,value:string){const groups=messageGroups(config.chatNodes[nodeIndex]);groups[group]=value.split('\n');changeNode(nodeIndex,{messages:groups});}
 function optionValue(nodeIndex:number,optionIndex:number,values:Partial<NonNullable<ChatNode['options']>[number]>){changeNode(nodeIndex,{options:config.chatNodes[nodeIndex].options?.map((option,i)=>i===optionIndex?{...option,...values}:option)});}
 function applyJSON(){try{config=importChat(json);expanded=expanded.filter(id=>config.chatNodes.some(node=>node.id===id));json=JSON.stringify(config,null,2);error='';return true;}catch(e){error=(e as Error).message;return false;}}
 function switchTab(next:typeof tab){if(tab==='json'&&!applyJSON())return;if(next==='json')json=JSON.stringify(config,null,2);if(next==='preview'){try{preview=importChat(JSON.stringify(config));previewRevision++;}catch(e){error=(e as Error).message;return;}}tab=next;error='';}
 function apply(){if(tab==='json'&&!applyJSON())return;try{if(!name.trim()||name.trim().length>120)throw Error('Escribe un nombre de hasta 120 caracteres.');onapply(name.trim(),importChat(JSON.stringify(config)));}catch(e){error=(e as Error).message;}}
 async function importFile(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];fileInput.value='';if(!file)return;try{if(file.size>MAX_CHAT_BYTES)throw Error('El JSON no puede superar 2 MB.');const imported=importChat(await file.text());if(dirty&&!confirm('¿Sustituir los cambios actuales por el JSON importado?'))return;config=imported;expanded=[config.chatNodes[0].id];tab='visual';error='';}catch(e){error=(e as Error).message;}}
 function exportJSON(){if(tab==='json'&&!applyJSON())return;try{parseChat(config);downloadBlob(new Blob([JSON.stringify(config,null,2)],{type:'application/json'}),'conversacion.json');error='';}catch(e){error=(e as Error).message;}}
</script>
<svelte:window onbeforeunload={unload} onkeydown={keyDown}/>
<section class="chat-editor" aria-label="Editor de conversación">
 <ModuleEditorHeader title="Conversación" context={title} onclose={leave}/>
 <details class="settings"><summary>Nombre y avatar</summary><div><label>Nombre de la conversación<input bind:value={name} maxlength="120"/></label><label>Avatar (URL)<input value={config.avatar??''} placeholder="https://… o /imagen.png" onchange={event=>config={...config,avatar:event.currentTarget.value}}/></label></div></details>
 <nav aria-label="Vistas del editor de conversación"><div class="tabs"><button class:active={tab==='visual'} aria-pressed={tab==='visual'} onclick={()=>switchTab('visual')}>Nodos</button><button class:active={tab==='json'} aria-pressed={tab==='json'} onclick={()=>switchTab('json')}>JSON</button><button class:active={tab==='preview'} aria-pressed={tab==='preview'} onclick={()=>switchTab('preview')}><Play size={15}/> Probar</button></div><div class="tools"><button class="icon" aria-label="Importar JSON de conversación" title="Importar JSON" onclick={()=>fileInput.click()}><Upload size={16}/></button><button class="icon" aria-label="Exportar JSON de conversación" title="Exportar JSON" onclick={exportJSON}><Download size={16}/></button></div></nav>
 <input class="hidden" bind:this={fileInput} type="file" accept=".json,application/json" onchange={importFile}/>
 {#if error}<p class="error" role="alert">{error}</p>{/if}
 <div class="content">
 {#if tab==='visual'}
  <section class="visual-nodes" bind:this={visualList} aria-label="Nodos de conversación"><div class="list-toolbar"><small>{config.chatNodes.length} nodos · el primero inicia el chat</small><button onclick={toggleAll}>{config.chatNodes.every(node=>expanded.includes(node.id))?'Contraer todos':'Expandir todos'}</button></div>
   <div class="node-list" role="list">
   {#each config.chatNodes as node,i (node.id)}
    <article class="node-card" class:success={node.id==='success'} class:fail={node.id==='fail'} role="listitem" aria-label={'Nodo '+node.id}>
     <div class="node-header"><button class="node-toggle" data-node-toggle={node.id} aria-expanded={expanded.includes(node.id)} aria-controls={'chat-node-content-'+i} aria-label={(expanded.includes(node.id)?'Contraer':'Expandir')+' nodo '+node.id} onclick={()=>toggleNode(node.id)}>{#if expanded.includes(node.id)}<ChevronDown size={17}/>{:else}<ChevronRight size={17}/>{/if}<span><strong>{i+1}. {node.id==='success'?'Éxito':node.id==='fail'?'Fallo':node.id}{#if i===0}<small class="entry">Inicio</small>{/if}</strong><small class="node-excerpt">{messageGroups(node)[0]?.[0]?.replace(/<[^>]*>/g,'')??'Sin mensajes'}</small></span></button><div class="node-actions"><button class="icon" aria-label={'Añadir nodo después de '+node.id} title="Añadir después" disabled={config.chatNodes.length>=256} onclick={()=>addNode(undefined,i)}><Plus size={15}/></button><button class="icon" aria-label={'Subir nodo '+node.id} title="Subir nodo" disabled={i===0} onclick={()=>move(i,-1)}><ChevronUp size={15}/></button><button class="icon" aria-label={'Bajar nodo '+node.id} title="Bajar nodo" disabled={i===config.chatNodes.length-1} onclick={()=>move(i,1)}><ChevronDown size={15}/></button><button class="icon danger" aria-label={'Eliminar nodo '+node.id} title="Eliminar nodo" onclick={()=>remove(i)}><Trash2 size={15}/></button></div></div>
     <div id={'chat-node-content-'+i} class="node-body" hidden={!expanded.includes(node.id)}><label>Identificador del nodo<input aria-label={'Identificador del nodo '+node.id} value={node.id} onchange={event=>{if(!rename(i,event.currentTarget.value))event.currentTarget.value=node.id;}}/></label>
   <h3>Mensajes</h3>
   {#each messageGroups(node) as group,g}<div class="message"><label>{g===0?'Primera visita':'Visita '+(g+1)}<textarea rows="4" aria-label={'Mensajes de '+node.id+', visita '+(g+1)} value={group.join('\n')} oninput={event=>groupText(i,g,event.currentTarget.value)}></textarea></label><button class="icon danger" aria-label={'Eliminar mensajes de '+node.id+', visita '+(g+1)} onclick={()=>changeNode(i,{messages:messageGroups(node).filter((_,i)=>i!==g)})}><Trash2 size={16}/></button></div>{/each}
   <p class="hint">Una línea por mensaje. Cada grupo se muestra al volver a este nodo. Admite el HTML del chat original.</p><button onclick={()=>changeNode(i,{messages:[...messageGroups(node),['Nuevo mensaje']]})}><Plus size={15}/> Añadir grupo de mensajes</button>
   <h3>Respuestas</h3>{#each node.options??[] as option,o}<div class="answer"><label>Respuesta {o+1}<input value={option.text} oninput={event=>optionValue(i,o,{text:event.currentTarget.value})}/></label><label>Destino<select value={option.home?'home:':option.target?'node:'+option.target:''} onchange={event=>optionValue(i,o,event.currentTarget.value==='home:'?{home:true,target:undefined}:{home:false,target:event.currentTarget.value.slice(5)})}><option value="" disabled>Elegir nodo…</option><option value="home:">Volver al inicio</option>{#each config.chatNodes as target}<option value={'node:'+target.id}>{target.id}</option>{/each}</select></label><button class="icon danger" aria-label={'Eliminar respuesta '+(o+1)+' de '+node.id} onclick={()=>changeNode(i,{options:node.options?.filter((_,i)=>i!==o)})}><Trash2 size={16}/></button></div>{/each}
   <button onclick={()=>changeNode(i,{options:[...(node.options??[]),{text:'Continuar',target:config.chatNodes.find(n=>n.id==='success')?.id??config.chatNodes[0].id}]})}><Plus size={15}/> Añadir respuesta</button>
   <details><summary>Propiedades avanzadas</summary><p class="hint">Los campos adicionales del JSON se conservan. Puedes editar premios, penalizaciones y otras propiedades en la pestaña JSON. El juego registra el avance; no aplica los premios de RoutingTales.</p></details>
     </div>
    </article>
   {/each}
   </div>
   <button class="add-node" disabled={config.chatNodes.length>=256} onclick={()=>addNode()}><Plus size={17}/> Añadir nodo</button><div class="endings"><button onclick={()=>addNode('success')}>+ Nodo de éxito</button><button onclick={()=>addNode('fail')}>+ Nodo de fallo</button></div>
  </section>
 {:else if tab==='json'}<section class="json-panel"><label for="conversation-json">JSON de RoutingTales</label><textarea id="conversation-json" bind:value={json} spellcheck="false"></textarea><button onclick={applyJSON}>Validar y aplicar JSON</button></section>
 {:else if preview}<section class="preview" aria-label="Prueba de conversación">{#key previewRevision}<RoutingTalesChat resource="preview" config={preview} progressKey="preview" storage={previewStorage} onclose={()=>switchTab('visual')}/>{/key}<button onclick={()=>switchTab('preview')}>Reiniciar prueba</button></section>{/if}
 </div>
 <footer>{#if discarding}<div class="discard" role="alertdialog" aria-label="Cambios de conversación pendientes" tabindex="-1" bind:this={discardMessage}><p>Hay cambios sin aplicar. ¿Quieres descartarlos?</p><div class="footer-actions"><button onclick={()=>discarding=false}>Seguir editando</button><button class="danger" onclick={onclose}>Descartar y volver</button></div></div>{:else}<div>{#if uses>1}<span>Vinculada a {uses} elementos.</span>{/if}<small>Aplica los cambios y después guarda la aventura.</small></div><div class="footer-actions"><button onclick={leave} aria-label="Cancelar edición de conversación">Cancelar</button><button class="primary" onclick={apply} aria-label="Aplicar conversación"><Save size={17}/> Aplicar</button></div>{/if}</footer>
</section>
<style>
 .chat-editor{display:flex;flex-direction:column;height:100%;min-height:0;min-width:0;color:#28354b;background:#fffef8;overflow:hidden}footer{display:flex;align-items:center;gap:12px;padding:16px;flex-shrink:0}small,.hint{font-size:12px;color:#65748b}button{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:1px solid #dce1ec;background:white;border-radius:8px;padding:8px 11px;font:inherit;font-size:13px;color:inherit;cursor:pointer}button:disabled{opacity:.4;cursor:default}button:hover:not(:disabled){background:#eef2fa}.icon{padding:8px;flex-shrink:0}.danger{color:#ad3448}input,textarea,select{width:100%;box-sizing:border-box;padding:9px;border:1px solid #cfd8e5;border-radius:7px;font:inherit;font-size:13px;color:inherit;background:#fff}textarea{resize:vertical;line-height:1.5}label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:600;min-width:0}.settings{padding:12px 16px;margin:0;flex-shrink:0}.settings summary{font-size:12px;cursor:pointer}.settings>div{display:grid;gap:10px;padding-top:10px}nav{display:flex;align-items:center;justify-content:space-between;padding:0 16px 12px;gap:12px;border-bottom:1px solid #e7ebf1;flex-wrap:wrap}.tabs,.tools{display:flex;gap:6px}.active{background:#eef1ff;color:#4355ab;border-color:#8c9ad0}.hidden{display:none}.content{display:flex;flex-direction:column;flex:1;min-height:0;overflow:auto;scrollbar-gutter:stable}.visual-nodes{padding:12px;min-width:0}.list-toolbar{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:12px}.list-toolbar small{font-size:11px}.list-toolbar button{font-size:11px;white-space:nowrap;padding:6px 8px}.node-list{display:flex;flex-direction:column;gap:12px}.node-card{border:1px solid #dce1ec;background:#fff;border-radius:10px;overflow:hidden;flex-shrink:0}.node-header{display:flex;align-items:center;gap:4px;padding:8px;background:#f5f7fb}.node-toggle{display:flex;align-items:center;gap:5px;min-width:0;flex:1;border:0;background:transparent;padding:4px;text-align:left;justify-content:flex-start}.node-toggle>span{display:block;min-width:0;flex:1}.node-toggle strong{display:flex;align-items:center;gap:5px;flex-wrap:wrap;font-size:12px;overflow-wrap:anywhere}.node-toggle>:global(svg){flex-shrink:0}.node-excerpt{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px;margin-top:4px}.entry{padding:2px 4px;border-radius:4px;background:#e5ebff;font-size:9px;color:#4355ab}.node-actions{display:flex;gap:3px;flex-shrink:0}.node-actions .icon{padding:6px}.node-body{padding:12px;border-top:1px solid #e7ebf1}.node-body[hidden]{display:none}.node-card.success{border-color:#9dc3a7}.success .node-header{background:#edf7ef}.node-card.fail{border-color:#dcb0b0}.fail .node-header{background:#fff1f1}.add-node{width:100%;margin-top:14px;padding:12px;border-style:dashed;background:#f7f9fc}.endings{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}.endings button{flex:1;font-size:12px}h3{font-size:14px;margin:18px 0 10px}.message{display:flex;align-items:flex-start;gap:8px;margin-bottom:12px}.message label{flex:1}.message button{margin-top:21px}.answer{display:grid;grid-template-columns:minmax(0,1fr) minmax(120px,.7fr) auto;align-items:end;gap:8px;margin-bottom:12px}.hint{line-height:1.5;margin:8px 0 12px}details{margin-top:24px;font-size:13px}.json-panel{display:flex;flex-direction:column;flex:1;padding:20px;gap:12px;min-height:0}.json-panel textarea{flex:1;min-height:180px;resize:none;font-family:monospace}.json-panel button{align-self:flex-start}.preview{display:flex;flex-direction:column;flex:1;min-height:0;padding:16px;gap:10px}.preview>button{align-self:center}footer{border-top:1px solid #e7ebf1;flex-direction:column;align-items:stretch;background:#fffef8}footer div{font-size:12px}footer .footer-actions{display:flex;gap:8px}footer .footer-actions>button{flex:1}.footer-actions .primary{flex:2}.discard{width:100%}.discard p{margin:0 0 12px;font-size:13px;color:#835522;line-height:1.5}.discard .footer-actions>button{white-space:normal}.discard:focus{outline:none}.primary{background:#4355ab;color:white;border-color:#4355ab;white-space:nowrap}.primary:hover:not(:disabled){background:#354591}.error{margin:0;padding:10px 20px;background:#fff0f0;color:#a72f43;font-size:13px;flex-shrink:0}input:focus,textarea:focus,select:focus,button:focus-visible{outline:2px solid #7587d8;outline-offset:2px}@media(max-width:450px){footer{padding:12px}nav{padding:0 12px 12px;gap:6px}nav .tabs button{padding:8px}.answer{grid-template-columns:minmax(0,1fr) auto}.answer label:first-child{grid-column:1/-1}.node-actions{gap:2px}.node-actions .icon{padding:5px}}
</style>
